/* 3. Off-Canvas Drawer Layout & Animation */
body.fo-nav-lock {
  overflow: hidden !important;
}

.fo-mobile-nav {
  position: fixed !important;
  top: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  width: min(100%, 32rem) !important;
  height: 100dvh !important;
  min-height: 100dvh !important;
  padding: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  color: #0B1020 !important;
  background: rgba(255, 255, 255, 0.985) !important;
  backdrop-filter: blur(28px) saturate(190%) !important;
  -webkit-backdrop-filter: blur(28px) saturate(190%) !important;
  border-left: 1px solid rgba(13, 13, 13, 0.08) !important;
  box-shadow: -12px 0 40px rgba(13, 13, 13, 0.16) !important;
  transform: translateX(100%) !important;
  opacity: 0 !important;
  pointer-events: none !important;
  transition: transform 0.36s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.2s ease !important;
  z-index: 999999 !important;
  box-sizing: border-box !important;
}

.fo-header-sticky-root.has-mobile-open .fo-mobile-nav,
body.fo-mobile-open .fo-mobile-nav {
  transform: translateX(0) !important;
  opacity: 1 !important;
  pointer-events: auto !important;
}

.fo-mobile-scrim {
  display: block !important;
  position: fixed !important;
  inset: 0 !important;
  background: rgba(13, 13, 13, 0.45) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  border: 0 !important;
  z-index: 999998 !important;
  opacity: 0 !important;
  pointer-events: none !important;
  transition: opacity 0.3s ease !important;
}

.fo-header-sticky-root.has-mobile-open .fo-mobile-scrim,
body.fo-mobile-open .fo-mobile-scrim {
  opacity: 1 !important;
  pointer-events: auto !important;
}

/* 4. Drawer Top Bar */
.fo-mobile-nav__top {
  min-height: 70px !important;
  height: 70px !important;
  padding: 0 24px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
